def prepare_deliveries(store, recipient_ids: list[int], event: str) -> list[dict]:
    unique_ids = list(dict.fromkeys(recipient_ids))
    if not unique_ids:
        return []
    subscriptions = store.get_subscriptions(unique_ids)
    deliveries = []
    for recipient_id in unique_ids:
        subscription = subscriptions.get(recipient_id)
        if subscription and subscription["active"]:
            deliveries.append(
                {"recipient_id": recipient_id, "channel": subscription["channel"], "event": event}
            )
    return deliveries
